/**
 * The official club crest. Its scroll lettering is black, so on dark surfaces the
 * `dark` variant is used, where only that lettering is white (see
 * scripts/make-logo-variants.mjs). Every other colour is the crest as supplied.
 */
export type LogoTone = 'light' | 'dark';

/** Widths generated by scripts/make-logo-variants.mjs. */
export const LOGO_WIDTHS = [160, 320, 640] as const;
/** Intrinsic proportions of the crest (1323 × 1189). */
export const LOGO_RATIO = { width: 1323, height: 1189 } as const;

export const logoSrc = (tone: LogoTone, width: (typeof LOGO_WIDTHS)[number] = 320, format: 'png' | 'webp' = 'png') =>
  `/assets/brand/brid-town-badge-${tone}-${width}.${format}`;

export const logoSrcset = (tone: LogoTone, format: 'png' | 'webp') =>
  LOGO_WIDTHS.map((w) => `${logoSrc(tone, w, format)} ${w}w`).join(', ');

/** Shown on unnamed placeholder cards and for players awaiting a photo (dark card background). */
export const squadLogo = logoSrc('dark', 640);

/** Full-size crest for social sharing previews. */
export const shareImage = '/assets/brand/brid-town-badge-black.png';
